<h1>Preventivo</h1><p><?= esc($tenant['tenant_name'] ?? $tenant['name'] ?? 'AmbulatorioFacile') ?></p><p>Riferimento: <?= esc($row['id']) ?><br>Data: <?= esc($d['date']) ?> · Valido fino al: <?= esc($row['expires_on']) ?></p><p>Paziente: <?= esc($patient['patient_name'] ?? 'Paziente #'.$row['patient_id']) ?></p><table><tr><th>Prestazione</th><th>Q.tà</th><th>Prezzo EUR</th><th>Totale EUR</th></tr><?php foreach($d['lines'] as $l): ?><tr><td><?= esc($l['description']) ?><br><small><?= esc($l['code'].' · '.$l['tax_note']) ?></small></td><td><?= (int)$l['quantity'] ?></td><td><?= $money($l['unit_cents']) ?></td><td><?= $money($l['total_cents']) ?></td></tr><?php endforeach ?></table><p class="total">Sconto: <?= $money($d['discount_cents']) ?><br><strong>Totale: <?= $money($row['total_cents']) ?></strong></p><p><?= nl2br(esc($d['notes'])) ?></p><footer>Documento non fiscale. Prezzi e condizioni riferiti al preventivo indicato. Revisione <?= (int)$row['revision'] ?>.</footer></body></html>
